    const ok = [];
    for (const b of want) {
      if (!b || ok.length >= MAX_BLOCKS) continue;
      const start = Number(b.start), count = Number(b.count);
      if (!Number.isInteger(start) || !Number.isInteger(count)) continue;
      if (start < 0 || start > 0xffff || count < 1 || start + count > 0x10000) continue;
