  const byteOrder = (conn.byte_order === 'little' || conn.byte_order === 'big') ? conn.byte_order : 'auto';
  msg.kostal = {
    conn: {
      ip, port,
      unit_id: num(conn.unit_id, 71),
      invert_grid_sign: !!conn.invert_grid_sign,
      invert_batt_sign: !!conn.invert_batt_sign,
      byte_order: byteOrder
    },
    target: ip + ':' + port,
    reads: KOSTAL_READS.map((r) => ({ start: r.start, count: r.count }))
  };
  node.status({ fill: 'blue', shape: 'dot', text: 'KOSTAL ' + sel.family + ' @ ' + ip + ':' + port });
  return [null, null, null, null, msg, null, null, null];
}
if (sel.communication === 'kaco_http') {
