  // Muss kaco/kaco-http.js FAMILIES entsprechen (flows-sync-Waechter): das
  // hybride Profil holt seine PV von der DC-Seite, weil die AC-Leistung eines
  // Hybriden PV + Entladung - Ladung ist.
  const KACO_HTTP_FAMILIES = { kaco_http: false, kaco_http_hybrid: true };
  if (!(sel.family in KACO_HTTP_FAMILIES)) return idle('unbekannte KACO-Familie: ' + sel.family);
  const port = num(conn.port, 8484);
  const insecure = !!conn.insecure_tls;
  const scheme = insecure ? 'https' : 'http';
  msg.kaco = {
    conn: {
      ip, port, scheme,
      serial: (typeof conn.serial === 'string' ? conn.serial : '').trim(),
      insecure_tls: insecure,
      invert_grid_sign: !!conn.invert_grid_sign,
      invert_batt_sign: !!conn.invert_batt_sign
    },
    family: sel.family,
    has_battery: KACO_HTTP_FAMILIES[sel.family],
    target: ip + ':' + port
  };
