const GRANT_TTL_MS = 5000;
const ONESHOT_YIELD_TICKS = 6;
const nowLock = Date.now();
const reserve = flow.get(oneKey) || null;
const reserveAt = (reserve && Number(reserve.at) > 0) ? Number(reserve.at) : 0;
const grant = flow.get(grantKey) || null;
const grantAt = (grant && Number(grant.at) > 0) ? Number(grant.at) : 0;
