    const sf = s16(regs[off.Hz_SF]);
    const v = raw * Math.pow(10, sf);
    if (isFinite(v)) hz = round1(v);
  } else {
    const v = f32(regs[off.Hz], regs[off.Hz + 1]);
    if (isFinite(v)) hz = round1(v);
