      for (const w of (ctrl.writes || [])) { txid = (txid + 1) & 0xffff; const wt = txid; await txn(buildWrite(txid, w.addr, w.value), (b) => parseWrite(b, wt)); }
      const registers = [];
      for (const rb of ctrl.readbacks) { txid = (txid + 1) & 0xffff; const rt = txid; const regs = await txn(buildRead(txid, rb.addr, 1), (b) => parseRead(b, rt)); const actual = regs[0] & 0xffff; const tol = rb.tolerance || 0; const entry = { role: rb.role, fc: 3, addr: rb.addr, commanded_raw: rb.expect & 0xffff, actual_raw: actual, match: Math.abs(actual - (rb.expect & 0xffff)) <= tol }; if (rb.role === 'battery_power') { entry.commanded_kw = s16(rb.expect) / 100; entry.actual_kw = s16(actual) / 100; } if (rb.role === 'pv_limit') { entry.commanded_kw = (rb.expect & 0xffff) === 0xffff ? null : rb.expect / 100; entry.actual_kw = actual === 0xffff ? null : actual / 100; } registers.push(entry); }
      context.set('ctxid', txid);
      const all = registers.every((r) => r.match);
      node.status({ fill: all ? 'green' : 'red', shape: 'dot', text: all ? ('bestätigt (' + registers.length + ')') : 'Abweichung' });
      const sp = msg.setpoint || {};
      // `mode` is the EVIDENCE half of the native self-regulation: only a cycle
      // that really ran the native primitive says 'native', so 'we stopped writing'
      // and 'we died' can never look the same to the core (which withdraws an
      // intent it does not see confirmed). 'release' / 'normal' unchanged.
      const mode = ctrl.mode === 'release' ? 'release' : (ctrl.mode === 'native' ? 'native' : 'normal');
      msg.payload = { ts: new Date().toISOString(), family: ctrl.family, source: sp.source || '', slot_start: sp.slot_start, control_enabled: !!ctrl.controlEnabled, certified: !!ctrl.certified, mode: mode, registers: registers };
      // The device's own answer to 'can you charge from the grid?', read from the
      // register the adapter named. Deliberately OUTSIDE the commanded-vs-actual
      // comparison (like remote_status_raw) so it can neither fabricate nor break
      // all_match - it is a separate statement, and its ABSENCE means 'the device
      // did not say', which on an EEG site counts as not proven.
      if (mode === 'native' && ctrl.gridChargeProof) {
        const g = ctrl.gridChargeProof;
        txid = (txid + 1) & 0xffff; const gt = txid;
        try { const gr = await txn(buildRead(txid, g.addr, 1), (b) => parseRead(b, gt)); msg.payload.native = { grid_charge_blocked: Math.abs((gr[0] & 0xffff) - (g.expect & 0xffff)) <= (g.tolerance || 0) }; } catch (e) { /* no answer = no statement */ }
        context.set('ctxid', txid);
      }
      // K4b: WHICH intent the executed primitive realises - only on a cycle that
      // ran it, so the core never counts an E-down hand-over as proof of a
      // charge-side intent (or any hand-over as proof of a different one).
      if (mode === 'native' && typeof ctrl.nativeIntent === 'string' && ctrl.nativeIntent !== '') {
        msg.payload.native = Object.assign({}, msg.payload.native || {}, { intent: ctrl.nativeIntent });
      }
      // K4b: what this selection has a certified lever for (every cycle).
      const ncaps = msg.nativeCapabilities;
      if (ncaps && Array.isArray(ncaps.intents)) {
        msg.payload.native_capabilities = { intents: ncaps.intents.slice(), window: ncaps.window === true, persistent: ncaps.persistent === true };
      }
      finish(null, msg);
    } catch (e) { finish(e); }
  });
}));
